const T = {
  bg: '#080808', green: '#aaff00', purple: '#7b2fff',
  card: '#141414', border: '#1e1e1e', muted: '#555', white: '#fff',
};

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@300;400;500;600;700;800;900&display=swap');
*{box-sizing:border-box;margin:0;padding:0}
body,html{background:#080808;color:#fff;font-family:'Barlow Condensed',sans-serif;height:100%;overflow:hidden}
::-webkit-scrollbar{width:4px}::-webkit-scrollbar-track{background:#080808}::-webkit-scrollbar-thumb{background:#aaff00;border-radius:2px}
input,textarea,select{font-family:'Barlow Condensed',sans-serif;background:#1a1a1a;color:#fff;border:1px solid #1e1e1e;border-radius:6px;padding:10px 14px;width:100%;font-size:16px;outline:none;transition:border-color 0.2s}
input:focus,textarea:focus,select:focus{border-color:#aaff00}
select option{background:#1a1a1a}
input[type=range]{-webkit-appearance:none;height:6px;border:none;border-radius:3px;outline:none;cursor:pointer;width:100%;padding:0}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:22px;height:22px;border-radius:50%;background:#aaff00;cursor:pointer;box-shadow:0 0 10px #aaff0066}
textarea{resize:vertical;min-height:80px}
@keyframes fadeIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.15}}
@keyframes logoGlow{0%,100%{text-shadow:0 0 20px #aaff0055,0 0 40px #aaff0022}50%{text-shadow:0 0 40px #aaff0099,0 0 80px #aaff0044}}
@keyframes appear{from{opacity:0;transform:scale(0.92)}to{opacity:1;transform:scale(1)}}
@keyframes slideUp{from{transform:translateY(24px);opacity:0}to{transform:translateY(0);opacity:1}}
.spl-logo{animation:appear 0.9s ease forwards}
.spl-title{animation:fadeIn 0.7s 0.5s ease both}
.spl-sub{animation:fadeIn 0.7s 0.9s ease both}
.spl-dots{animation:fadeIn 0.5s 1.3s ease both}
.tab-anim{animation:slideUp 0.28s ease forwards}
`;

async function sg(key) {
  try { const r = await window.storage.get(key); return r ? JSON.parse(r.value) : null; }
  catch { return null; }
}
async function ss(key, val) {
  try { await window.storage.set(key, JSON.stringify(val)); } catch(e) { console.error(e); }
}

function Slider({ label, value, onChange }) {
  const pct = ((value - 1) / 9) * 100;
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
        <span style={{ color: '#aaa', fontSize: 14, textTransform: 'uppercase', letterSpacing: '0.06em' }}>{label}</span>
        <span style={{ color: T.green, fontWeight: 900, fontSize: 22, minWidth: 28, textAlign: 'right', lineHeight: 1 }}>{value}</span>
      </div>
      <input type="range" min={1} max={10} value={value}
        onChange={e => onChange(+e.target.value)}
        style={{ background: `linear-gradient(to right,${T.green} ${pct}%,#2a2a2a ${pct}%)` }} />
    </div>
  );
}

function SecHead({ children, color }) {
  const c = color || T.green;
  return (
    <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', color: c, marginBottom: 12, paddingBottom: 6, borderBottom: `1px solid ${c}33`, marginTop: 6 }}>
      {children}
    </div>
  );
}

function Field({ label, value, onChange, placeholder, multi, rows }) {
  const r = rows || 3;
  return (
    <div style={{ marginBottom: 14 }}>
      {label && <div style={{ fontSize: 11, color: '#666', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: 6 }}>{label}</div>}
      {multi
        ? <textarea value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} rows={r} />
        : <input type="text" value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} />}
    </div>
  );
}

function Toast({ msg, color }) {
  const c = color || T.green;
  if (!msg) return null;
  return (
    <div style={{ background: `${c}18`, border: `1px solid ${c}44`, color: c, padding: '10px 14px', borderRadius: 6, marginBottom: 16, fontSize: 14, fontWeight: 700, letterSpacing: '0.06em', animation: 'fadeIn 0.3s ease' }}>
      \u2713 {msg}
    </div>
  );
}

function CardDisplay({ card, onDelete }) {
  const [exp, setExp] = useState(false);
  const ip = card.type === 'player';
  const ac = ip ? T.green : T.purple;
  const cmL = { timeAtNet: 'Time at Net', alignmentWithPartner: 'Align w/ Partner', overallPositioning: 'Positioning' };
  return (
    <div onClick={() => setExp(!exp)} style={{ background: T.card, border: `1px solid ${ac}33`, borderLeft: `3px solid ${ac}`, borderRadius: 8, padding: 14, marginBottom: 10, cursor: 'pointer' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.14em', color: ac, textTransform: 'uppercase' }}>
            {ip ? 'PLAYER' : (card.eventType || 'EVENT')}
          </div>
          <div style={{ fontSize: 19, fontWeight: 700, marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {ip ? (card.playerName || 'Unnamed Player') : (card.topic || 'Event Session')}
          </div>
          <div style={{ fontSize: 12, color: '#555', marginTop: 2 }}>{card.date}</div>
        </div>
        <div style={{ color: ac, fontSize: 14, opacity: 0.5, paddingLeft: 8, flexShrink: 0 }}>{exp ? '\u25b2' : '\u25bc'}</div>
      </div>
      {exp && (
        <div onClick={e => e.stopPropagation()} style={{ marginTop: 14, borderTop: '1px solid #1e1e1e', paddingTop: 14 }}>
          {ip && (
            <div>
              <div style={{ marginBottom: 12 }}>
                <div style={{ fontSize: 10, color: '#444', textTransform: 'uppercase', letterSpacing: '0.12em', marginBottom: 8 }}>Shot Skills</div>
                {['glass', 'overheads', 'volleys'].map(k => (
                  <div key={k} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                    <span style={{ fontSize: 13, color: '#888', textTransform: 'capitalize', width: 90 }}>{k}</span>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <div style={{ width: 80, height: 4, background: '#222', borderRadius: 2 }}>
                        <div style={{ width: ((card[k] / 10) * 100) + '%', height: '100%', background: T.green, borderRadius: 2 }} />
                      </div>
                      <span style={{ color: T.green, fontWeight: 800, fontSize: 15, width: 22, textAlign: 'right' }}>{card[k]}</span>
                    </div>
                  </div>
                ))}
              </div>
              <div style={{ marginBottom: 12 }}>
                <div style={{ fontSize: 10, color: '#444', textTransform: 'uppercase', letterSpacing: '0.12em', marginBottom: 8 }}>Court Management</div>
                {['timeAtNet', 'alignmentWithPartner', 'overallPositioning'].map(k => (
                  <div key={k} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                    <span style={{ fontSize: 13, color: '#888', width: 130 }}>{cmL[k]}</span>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <div style={{ width: 80, height: 4, background: '#222', borderRadius: 2 }}>
                        <div style={{ width: ((card[k] / 10) * 100) + '%', height: '100%', background: T.purple, borderRadius: 2 }} />
                      </div>
                      <span style={{ color: T.purple, fontWeight: 800, fontSize: 15, width: 22, textAlign: 'right' }}>{card[k]}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
          {!ip && card.players && card.players.some(p => p) && (
            <div style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 10, color: '#444', textTransform: 'uppercase', letterSpacing: '0.12em', marginBottom: 8 }}>Players</div>
              {card.players.filter(p => p).map((p, i) => (
                <div key={i} style={{ fontSize: 13, color: '#ccc', marginBottom: 4 }}>
                  {p}{card.playerNotes && card.playerNotes[i] ? <span style={{ color: '#555', marginLeft: 8 }}>\u2014 {card.playerNotes[i]}</span> : null}
                </div>
              ))}
            </div>
          )}
          {card.topic ? <div style={{ marginBottom: 8 }}><span style={{ fontSize: 10, color: '#444', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Topic: </span><span style={{ fontSize: 14, color: '#ccc' }}>{card.topic}</span></div> : null}
          {card.sessionNotes ? (
            <div style={{ marginBottom: 8 }}>
              <div style={{ fontSize: 10, color: '#444', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: 4 }}>Notes</div>
              <div style={{ fontSize: 13, color: '#bbb', lineHeight: 1.55 }}>{card.sessionNotes}</div>
            </div>
          ) : null}
          {card.nextSessionFocus ? (
            <div style={{ marginBottom: 8 }}>
              <div style={{ fontSize: 10, color: '#444', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: 4 }}>Next Focus</div>
              <div style={{ fontSize: 13, color: T.green }}>{card.nextSessionFocus}</div>
            </div>
          ) : null}
          <button onClick={() => onDelete(card.id)} style={{ marginTop: 10, background: 'transparent', border: '1px solid #222', color: '#444', padding: '6px 14px', borderRadius: 4, cursor: 'pointer', fontSize: 12, fontFamily: "'Barlow Condensed',sans-serif", letterSpacing: '0.08em' }}>
            DELETE CARD
          </button>
        </div>
      )}
    </div>
  );
}

function Splash() {
  return (
    <div style={{ position: 'fixed', inset: 0, background: T.bg, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', fontFamily: "'Barlow Condensed',sans-serif" }}>
      <img src={LOGO_B64} alt="Vamos!" className="spl-logo" style={{ width: 220, marginBottom: 20 }} />
      <div className="spl-title" style={{ fontSize: 52, fontWeight: 900, letterSpacing: '0.14em', textTransform: 'uppercase', color: T.green, textShadow: '0 0 30px #aaff0055,0 0 60px #aaff0022', lineHeight: 1 }}>
        VIPER GLIDE
      </div>
      <div className="spl-sub" style={{ fontSize: 13, color: '#555', letterSpacing: '0.25em', textTransform: 'uppercase', marginTop: 8 }}>
        Coach Performance Tracker
      </div>
      <div className="spl-sub" style={{ fontSize: 11, color: '#333', letterSpacing: '0.18em', marginTop: 4 }}>
        by Follow the Viper
      </div>
      <div className="spl-dots" style={{ display: 'flex', gap: 8, marginTop: 36 }}>
        {[0, 1, 2].map(i => (
          <div key={i} style={{ width: 8, height: 8, borderRadius: '50%', background: T.green, animation: 'pulse 1.3s ' + (i * 0.22) + 's ease-in-out infinite' }} />
        ))}
      </div>
      <div style={{ position: 'absolute', bottom: 20, fontSize: 11, color: '#1e1e1e', letterSpacing: '0.14em' }}>#followtheviper</div>
    </div>
  );
}

function Onboarding({ name, setName, onDone }) {
  const [step, setStep] = useState(0);
  const bodies = [
    (
      <div>
        <div style={{ fontSize: 15, color: '#666', lineHeight: 1.7, marginBottom: 24 }}>
          Track every coaching session with precision. Record player performance, log events, and follow every player development over time.
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
          {[['\ud83d\udc0d', 'Be the Viper', 'Coaching identity'], ['\ud83d\udcca', 'Track Progress', '6 key metrics'], ['\ud83d\udc64', 'Player Cards', 'Individual sessions'], ['\ud83d\udcc5', 'Event Cards', 'Groups & tournaments']].map(function(item) {
            return (
              <div key={item[1]} style={{ background: '#111', border: '1px solid #1e1e1e', borderRadius: 8, padding: 14 }}>
                <div style={{ fontSize: 22, marginBottom: 6 }}>{item[0]}</div>
                <div style={{ fontSize: 13, fontWeight: 700, color: T.green, letterSpacing: '0.05em' }}>{item[1]}</div>
                <div style={{ fontSize: 11, color: '#444', marginTop: 3 }}>{item[2]}</div>
              </div>
            );
          })}
        </div>
      </div>
    ),
    (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
        <div style={{ background: '#111', border: '1px solid #aaff0033', borderLeft: '3px solid #aaff00', borderRadius: 8, padding: 16 }}>
          <div style={{ color: T.green, fontWeight: 700, fontSize: 13, letterSpacing: '0.1em', marginBottom: 8 }}>PLAYER CARD</div>
          <div style={{ color: '#777', fontSize: 14, lineHeight: 1.65 }}>
            Rate Glass, Overheads and Volleys plus court management across Net Play, Partner Alignment and Overall Positioning on 1-10 sliders. Add session notes and next focus.
          </div>
        </div>
        <div style={{ background: '#111', border: '1px solid #7b2fff33', borderLeft: '3px solid #7b2fff', borderRadius: 8, padding: 16 }}>
          <div style={{ color: T.purple, fontWeight: 700, fontSize: 13, letterSpacing: '0.1em', marginBottom: 8 }}>EVENT CARD</div>
          <div style={{ color: '#777', fontSize: 14, lineHeight: 1.65 }}>
            Log Individual Lessons, Group Lessons, Matchplay or Tournaments. Add up to 6 players with per-player notes plus overall session notes and next focus.
          </div>
        </div>
      </div>
    ),
    (
      <div>
        <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Enter your coach name..." autoFocus style={{ fontSize: 18, marginBottom: 12 }} />
        <div style={{ fontSize: 13, color: '#3a3a3a' }}>You can update this in the About tab any time.</div>
      </div>
    ),
  ];
  const titles = ["Welcome to\nViper Glide", "Two Card\nTypes", "What is Your\nName?"];
  const subs = ["Your coaching companion from Follow the Viper", "Built for every session you coach", "Pre-fill your coach name on every card"];
  const isLast = step === 2;
  return (
    <div style={{ position: 'fixed', inset: 0, background: T.bg, fontFamily: "'Barlow Condensed',sans-serif", display: 'flex', flexDirection: 'column', padding: '28px 24px 28px', overflow: 'hidden' }}>
      <div style={{ marginBottom: 24 }}>
        <img src={LOGO_B64} alt="Vamos!" style={{ height: 50 }} />
      </div>
      <div key={step} style={{ flex: 1, animation: 'fadeIn 0.35s ease', overflow: 'auto' }}>
        <div style={{ fontSize: 42, fontWeight: 900, letterSpacing: '0.04em', textTransform: 'uppercase', lineHeight: 1.08, marginBottom: 8, whiteSpace: 'pre-line' }}>{titles[step]}</div>
        <div style={{ color: T.green, fontSize: 14, letterSpacing: '0.08em', marginBottom: 22 }}>{subs[step]}</div>
        {bodies[step]}
      </div>
      <div style={{ display: 'flex', gap: 10, alignItems: 'center', marginTop: 16 }}>
        <div style={{ display: 'flex', gap: 6, flex: 1 }}>
          {[0, 1, 2].map(i => <div key={i} style={{ width: i === step ? 24 : 8, height: 8, borderRadius: 4, background: i === step ? T.green : '#222', transition: 'all 0.3s' }} />)}
        </div>
        {step > 0 && <button onClick={() => setStep(s => s - 1)} style={{ background: 'transparent', border: '1px solid #222', color: '#555', padding: '12px 18px', borderRadius: 8, cursor: 'pointer', fontSize: 14, fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 700, letterSpacing: '0.06em' }}>BACK</button>}
        <button onClick={isLast ? onDone : () => setStep(s => s + 1)} style={{ background: T.green, border: 'none', color: '#000', padding: '13px 28px', borderRadius: 8, cursor: 'pointer', fontSize: 16, fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 900, letterSpacing: '0.1em', textTransform: 'uppercase' }}>
          {isLast ? "LET'S GO!" : 'NEXT'}
        </button>
      </div>
    </div>
  );
}

function HomeTab({ cards, onDelete }) {
  const pc = cards.filter(c => c.type === 'player').length;
  const ec = cards.filter(c => c.type === 'event').length;
  return (
    <div style={{ padding: 16, paddingBottom: 90 }}>
      <div style={{ display: 'flex', gap: 10, marginBottom: 20 }}>
        {[[cards.length, 'Sessions', T.white], [pc, 'Player', T.green], [ec, 'Event', T.purple]].map(function(item) {
          return (
            <div key={item[1]} style={{ flex: 1, background: T.card, border: '1px solid #1a1a1a', borderRadius: 8, padding: '12px 8px', textAlign: 'center' }}>
              <div style={{ fontSize: 34, fontWeight: 900, color: item[2], lineHeight: 1 }}>{item[0]}</div>
              <div style={{ fontSize: 10, color: '#3a3a3a', textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 4 }}>{item[1]}</div>
            </div>
          );
        })}
      </div>
      <SecHead>Recent Sessions</SecHead>
      {cards.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '52px 20px' }}>
          <div style={{ fontSize: 20, fontWeight: 700, color: '#2a2a2a', marginBottom: 8 }}>No sessions yet</div>
          <div style={{ fontSize: 13, color: '#1e1e1e' }}>Tap Player or Event to log your first session</div>
        </div>
      ) : cards.slice(0, 20).map(c => <CardDisplay key={c.id} card={c} onDelete={onDelete} />)}
    </div>
  );
}

function PlayerTab({ form, setF, onSave, msg }) {
  const u = (k, v) => setF(f => Object.assign({}, f, { [k]: v }));
  return (
    <div style={{ padding: 16, paddingBottom: 90 }}>
      <Toast msg={msg} color={T.green} />
      <SecHead>Player</SecHead>
      <Field label="Player Name" value={form.playerName} onChange={v => u('playerName', v)} placeholder="Player's full name" />
      <div style={{ marginTop: 4 }}><SecHead color={T.green}>Shot Skills (1-10)</SecHead></div>
      <Slider label="Glass" value={form.glass} onChange={v => u('glass', v)} />
      <Slider label="Overheads" value={form.overheads} onChange={v => u('overheads', v)} />
      <Slider label="Volleys" value={form.volleys} onChange={v => u('volleys', v)} />
      <div style={{ marginTop: 4 }}><SecHead color={T.purple}>Court Management (1-10)</SecHead></div>
      <Slider label="Time at Net" value={form.timeAtNet} onChange={v => u('timeAtNet', v)} />
      <Slider label="Alignment with Partner" value={form.alignmentWithPartner} onChange={v => u('alignmentWithPartner', v)} />
      <Slider label="Overall Positioning" value={form.overallPositioning} onChange={v => u('overallPositioning', v)} />
      <div style={{ marginTop: 4 }}><SecHead>Notes</SecHead></div>
      <Field label="Player Notes" value={form.sessionNotes} onChange={v => u('sessionNotes', v)} placeholder="Notes on this player's session" multi={true} rows={4} />
      <Field label="Next Session Focus" value={form.nextSessionFocus} onChange={v => u('nextSessionFocus', v)} placeholder="Key areas for next time" multi={true} rows={3} />
      <button onClick={onSave} style={{ width: '100%', background: form.playerName ? T.green : '#1a1a1a', border: 'none', color: form.playerName ? '#000' : '#333', padding: 16, borderRadius: 10, cursor: form.playerName ? 'pointer' : 'default', fontSize: 18, fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 900, letterSpacing: '0.1em', textTransform: 'uppercase', marginTop: 16, transition: 'all 0.3s' }}>
        SAVE PLAYER CARD
      </button>
    </div>
  );
}

function PlayerPickerInput({ index, value, onChange, knownPlayers }) {
  const [open, setOpen] = useState(false);
  const filtered = knownPlayers.filter(n => n && n.toLowerCase().includes(value.toLowerCase()) && n !== value);
  const hasLinked = knownPlayers.includes(value);
  return (
    <div style={{ position: 'relative', marginBottom: 4 }}>
      <div style={{ position: 'relative' }}>
        <input
          type="text"
          value={value}
          onChange={e => { onChange(e.target.value); setOpen(true); }}
          onFocus={() => setOpen(true)}
          onBlur={() => setTimeout(() => setOpen(false), 150)}
          placeholder={'Player ' + (index + 1) + ' name'}
          style={{ paddingRight: hasLinked ? 36 : 14 }}
        />
        {hasLinked && (
          <div style={{ position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)', color: T.green, fontSize: 13, fontWeight: 700, letterSpacing: '0.06em', pointerEvents: 'none' }}>
            LINKED
          </div>
        )}
      </div>
      {open && filtered.length > 0 && (
        <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, background: '#1a1a1a', border: '1px solid #aaff0044', borderRadius: 6, zIndex: 50, overflow: 'hidden', marginTop: 2 }}>
          {filtered.map(n => (
            <div key={n} onMouseDown={() => { onChange(n); setOpen(false); }}
              style={{ padding: '10px 14px', cursor: 'pointer', fontSize: 15, color: T.green, borderBottom: '1px solid #222', fontWeight: 600 }}>
              {n}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function EventTab({ form, setF, onSave, msg, cards }) {
  const u = (k, v) => setF(f => Object.assign({}, f, { [k]: v }));
  const up = (i, v) => setF(f => { const p = f.players.slice(); p[i] = v; return Object.assign({}, f, { players: p }); });
  const un = (i, v) => setF(f => { const n = f.playerNotes.slice(); n[i] = v; return Object.assign({}, f, { playerNotes: n }); });
  const knownPlayers = Array.from(new Set((cards || []).filter(c => c.type === 'player' && c.playerName).map(c => c.playerName)));
  return (
    <div style={{ padding: 16, paddingBottom: 90 }}>
      <Toast msg={msg} color={T.purple} />
      <SecHead>Event Info</SecHead>
      <Field label="Event Title" value={form.eventTitle} onChange={v => u('eventTitle', v)} placeholder="e.g. Tuesday Group Session" />
      <Field label="Club / Venue" value={form.club} onChange={v => u('club', v)} placeholder="Club or venue name" />
      <div style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 11, color: '#666', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: 6 }}>Event Type</div>
        <select value={form.eventType} onChange={e => u('eventType', e.target.value)} style={{ fontWeight: 600 }}>
          <option>Individual Lesson</option>
          <option>Group Lesson</option>
          <option>Matchplay</option>
          <option>Tournament</option>
        </select>
      </div>
      <div style={{ marginTop: 4 }}><SecHead color={T.purple}>Players (up to 6)</SecHead></div>
      {knownPlayers.length > 0 && (
        <div style={{ fontSize: 11, color: '#444', marginBottom: 10, letterSpacing: '0.06em' }}>
          Type a name to link to an existing player card
        </div>
      )}
      {[0, 1, 2, 3, 4, 5].map(i => (
        <div key={i} style={{ marginBottom: 10 }}>
          <PlayerPickerInput index={i} value={form.players[i]} onChange={v => up(i, v)} knownPlayers={knownPlayers} />
          {form.players[i] ? <input type="text" value={form.playerNotes[i]} onChange={e => un(i, e.target.value)} placeholder={'Notes for ' + form.players[i]} style={{ background: '#111', fontSize: 14, padding: '8px 12px', color: '#888' }} /> : null}
        </div>
      ))}
      <div style={{ marginTop: 4 }}><SecHead>Session Notes</SecHead></div>
      <Field label="Topic" value={form.topic} onChange={v => u('topic', v)} placeholder="Session topic or theme" />
      <Field label="Session Notes" value={form.sessionNotes} onChange={v => u('sessionNotes', v)} placeholder="What happened in the session?" multi={true} rows={4} />
      <Field label="Next Session Focus" value={form.nextSessionFocus} onChange={v => u('nextSessionFocus', v)} placeholder="Key areas for next time" multi={true} rows={3} />
      <button onClick={onSave} style={{ width: '100%', background: T.purple, border: 'none', color: T.white, padding: 16, borderRadius: 10, cursor: 'pointer', fontSize: 18, fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 900, letterSpacing: '0.1em', textTransform: 'uppercase', marginTop: 16 }}>
        SAVE EVENT CARD
      </button>
    </div>
  );
}

function AboutTab({ name, setName, onSave }) {
  const [saved, setSaved] = useState(false);
  const handle = () => { onSave(); setSaved(true); setTimeout(() => setSaved(false), 2500); };
  return (
    <div style={{ padding: '20px 16px', paddingBottom: 90 }}>
      <div style={{ textAlign: 'center', marginBottom: 28, paddingTop: 8 }}>
        <img src={LOGO_B64} alt="Vamos!" style={{ width: 200, marginBottom: 12 }} />
        <div style={{ fontSize: 28, fontWeight: 900, color: T.green, letterSpacing: '0.12em', textTransform: 'uppercase' }}>VIPER GLIDE</div>
        <div style={{ fontSize: 12, color: '#333', letterSpacing: '0.2em', textTransform: 'uppercase', marginTop: 4 }}>Coach Performance Tracker by Follow the Viper</div>
      </div>
      <div style={{ background: T.card, border: '1px solid #1a1a1a', borderRadius: 10, padding: 16, marginBottom: 14 }}>
        <SecHead>Your Details</SecHead>
        <Field label="Coach Name" value={name} onChange={setName} placeholder="Enter your name" />
        {saved ? <div style={{ color: T.green, fontSize: 13, fontWeight: 700, marginBottom: 8, letterSpacing: '0.06em' }}>Saved</div> : null}
        <button onClick={handle} style={{ background: T.green, border: 'none', color: '#000', padding: '10px 22px', borderRadius: 6, cursor: 'pointer', fontSize: 14, fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 800, letterSpacing: '0.08em' }}>
          SAVE NAME
        </button>
      </div>
      <div style={{ background: T.card, border: '1px solid #1a1a1a', borderRadius: 10, padding: 16, marginBottom: 14 }}>
        <SecHead>About Follow the Viper</SecHead>
        <div style={{ fontSize: 15, color: '#777', lineHeight: 1.7, marginBottom: 10 }}>
          Follow the Viper is the UK independent padel platform built for players by players. Driving padel growth across Scotland and beyond.
        </div>
        <div style={{ fontSize: 15, color: '#777', lineHeight: 1.7 }}>
          Our racket comparison tool covers 236+ rackets across 23 brands. Viper Glide extends that mission into coaching excellence.
        </div>
      </div>
      <div style={{ background: T.card, border: '1px solid #1a1a1a', borderRadius: 10, padding: 16, marginBottom: 14 }}>
        <SecHead>Community</SecHead>
        <div style={{ fontSize: 15, color: '#777', lineHeight: 1.9 }}>
          <div>Viperistas - our coaching and player community</div>
          <div>Be the Viper - our coaching philosophy</div>
          <div style={{ marginTop: 8, color: '#3a3a3a' }}>followtheviper.com</div>
          <div style={{ color: '#3a3a3a' }}>@followtheviper</div>
        </div>
      </div>
      <div style={{ background: '#0d0a1a', border: '1px solid #7b2fff22', borderRadius: 10, padding: 16, marginBottom: 14 }}>
        <SecHead color={T.purple}>About This App</SecHead>
        <div style={{ fontSize: 14, color: '#555', lineHeight: 1.7 }}>
          Player Cards track shot quality and court management across 6 metrics on 1-10 sliders. Event Cards log groups, matchplay and tournaments with per-player notes. All data is stored locally on your device.
        </div>
      </div>
      <div style={{ textAlign: 'center', padding: '16px 0 8px', color: '#1e1e1e', fontSize: 12, letterSpacing: '0.14em' }}>
        #followtheviper - Viper Glide v1.0
      </div>
    </div>
  );
}

function Nav({ tab, setTab }) {
  const ts = [{ id: 'home', ic: 'HOME', lb: 'HOME' }, { id: 'player', ic: 'PLAYER', lb: 'PLAYER' }, { id: 'event', ic: 'EVENT', lb: 'EVENT' }, { id: 'about', ic: 'ABOUT', lb: 'ABOUT' }];
  return (
    <div style={{ position: 'fixed', bottom: 0, left: 0, right: 0, background: '#060606', borderTop: '1px solid #141414', display: 'flex', padding: '8px 0', zIndex: 100, boxShadow: '0 -4px 20px #00000088' }}>
      {ts.map(function(t) {
        const active = tab === t.id;
        const col = t.id === 'player' ? T.green : t.id === 'event' ? T.purple : T.white;
        const icons = { home: '\ud83c\udfe0', player: '\ud83d\udc64', event: '\ud83d\udcc5', about: '\u2139\ufe0f' };
        return (
          <button key={t.id} onClick={() => setTab(t.id)} style={{ flex: 1, background: 'transparent', border: 'none', cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3, padding: '4px 0', opacity: active ? 1 : 0.3, transition: 'opacity 0.2s' }}>
            <div style={{ fontSize: 20, lineHeight: 1 }}>{icons[t.id]}</div>
            <div style={{ fontSize: 10, fontFamily: "'Barlow Condensed',sans-serif", fontWeight: 700, letterSpacing: '0.1em', color: active ? col : T.white }}>{t.lb}</div>
            {active ? <div style={{ width: 22, height: 2, background: col, borderRadius: 1 }} /> : null}
          </button>
        );
      })}
    </div>
  );
}

function MainApp({ tab, setTab, cards, setCards, name, setName, pf, setPf, ef, setEf, savePl, saveEv, msg }) {
  const del = async function(id) { const nc = cards.filter(c => c.id !== id); setCards(nc); await ss('vg-cards', nc); };
  const saveN = async function() { const s = await sg('vg-settings') || {}; await ss('vg-settings', Object.assign({}, s, { coachName: name })); };
  useEffect(function() {
    if (name) {
      if (!pf.coachName) setPf(f => Object.assign({}, f, { coachName: name }));
      if (!ef.coachName) setEf(f => Object.assign({}, f, { coachName: name }));
    }
  }, [name]);
  const titles = { home: 'SESSIONS', player: 'PLAYER CARD', event: 'EVENT CARD', about: 'ABOUT' };
  return (
    <div style={{ position: 'fixed', inset: 0, background: T.bg, fontFamily: "'Barlow Condensed',sans-serif", display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', alignItems: 'center', padding: '8px 14px', background: '#060606', borderBottom: '1px solid #141414', flexShrink: 0, boxShadow: '0 2px 16px #00000066' }}>
        <img src={LOGO_B64} alt="Vamos!" style={{ height: 44, marginRight: 10 }} />
        <div>
          <div style={{ fontSize: 18, fontWeight: 900, letterSpacing: '0.12em', color: T.green, lineHeight: 1, textTransform: 'uppercase', textShadow: '0 0 20px #aaff0033' }}>VIPER GLIDE</div>
          <div style={{ fontSize: 10, color: '#333', letterSpacing: '0.16em', textTransform: 'uppercase', marginTop: 1 }}>{titles[tab]}</div>
        </div>
      </div>
      <div style={{ flex: 1, overflowY: 'auto', position: 'relative' }}>
        <div className="tab-anim" key={tab}>
          {tab === 'home' ? <HomeTab cards={cards} onDelete={del} /> : null}
          {tab === 'player' ? <PlayerTab form={pf} setF={setPf} onSave={savePl} msg={msg} /> : null}
          {tab === 'event' ? <EventTab form={ef} setF={setEf} onSave={saveEv} msg={msg} cards={cards} /> : null}
          {tab === 'about' ? <AboutTab name={name} setName={setName} onSave={saveN} /> : null}
        </div>
      </div>
      <Nav tab={tab} setTab={setTab} />
    </div>
  );
}

const DEF_PL = { coachName: '', club: '', playerName: '', glass: 5, overheads: 5, volleys: 5, timeAtNet: 5, alignmentWithPartner: 5, overallPositioning: 5, topic: '', sessionNotes: '', nextSessionFocus: '' };
const DEF_EV = { coachName: '', club: '', eventTitle: '', eventType: 'Individual Lesson', players: ['', '', '', '', '', ''], topic: '', sessionNotes: '', nextSessionFocus: '', playerNotes: ['', '', '', '', '', ''] };

export default function ViperGlide() {
  const [phase, setPhase] = useState('splash');
  const [tab, setTab] = useState('home');
  const [name, setName] = useState('');
  const [cards, setCards] = useState([]);
  const [pf, setPf] = useState(DEF_PL);
  const [ef, setEf] = useState(DEF_EV);
  const [msg, setMsg] = useState('');

  useEffect(function() {
    const style = document.createElement('style');
    style.textContent = CSS;
    document.head.appendChild(style);
    return function() { document.head.removeChild(style); };
  }, []);

  useEffect(function() {
    var init = async function() {
      const res = await Promise.all([sg('vg-settings'), sg('vg-cards')]);
      const settings = res[0];
      const stored = res[1];
      if (stored) setCards(stored);
      if (settings && settings.onboardingDone) {
        const n = settings.coachName || '';
        setName(n);
        setPf(f => Object.assign({}, f, { coachName: n }));
        setEf(f => Object.assign({}, f, { coachName: n }));
        setTimeout(function() { setPhase('main'); }, 2700);
      } else {
        setTimeout(function() { setPhase('onboarding'); }, 2700);
      }
    };
    init();
  }, []);

  const doneOnboarding = async function() {
    await ss('vg-settings', { onboardingDone: true, coachName: name });
    setPf(f => Object.assign({}, f, { coachName: name }));
    setEf(f => Object.assign({}, f, { coachName: name }));
    setPhase('main');
  };

  const savePl = async function() {
    const card = Object.assign({}, pf, { type: 'player', id: Date.now(), date: new Date().toLocaleDateString('en-GB') });
    const nc = [card].concat(cards);
    setCards(nc); await ss('vg-cards', nc);
    setMsg('Player card saved!'); setTimeout(function() { setMsg(''); }, 3000);
    setPf(Object.assign({}, DEF_PL, { coachName: name }));
    setTab('home');
  };

  const saveEv = async function() {
    const card = Object.assign({}, ef, { type: 'event', id: Date.now(), date: new Date().toLocaleDateString('en-GB') });
    const nc = [card].concat(cards);
    setCards(nc); await ss('vg-cards', nc);
    setMsg('Event card saved!'); setTimeout(function() { setMsg(''); }, 3000);
    setEf(Object.assign({}, DEF_EV, { coachName: name }));
    setTab('home');
  };

  if (phase === 'splash') return <Splash />;
  if (phase === 'onboarding') return <Onboarding name={name} setName={setName} onDone={doneOnboarding} />;
  return <MainApp tab={tab} setTab={setTab} cards={cards} setCards={setCards} name={name} setName={setName} pf={pf} setPf={setPf} ef={ef} setEf={setEf} savePl={savePl} saveEv={saveEv} msg={msg} />;
}
